const $=id=>document.getElementById(id);
let player,ready=false,wanted=false,customLines=[],timed=false;
const letterLines=['Enakku en Sindhu thaan venum.','Naan unna meet pannirukken.','Un voice kekkumbothu enakku theriyamale smile vandhudum.','For being Sindhu. Just Sindhu. ❤️','Adhu nee thaan, en Sindu ma.','I love you, Sindu ma. ❤️'];
const format=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
let lineIndex=-1;
function showToast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),5000)}
function setPlaying(playing){$('turntable').classList.toggle('playing',playing);$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause Magale':'Play Magale');}
window.onYouTubeIframeAPIReady=()=>{player=new YT.Player('youtube',{height:'200',width:'295',videoId:'FhhA5purigQ',playerVars:{playsinline:1,rel:0,start:58},events:{onReady:()=>{ready=true;player.setVolume(65);$('status').textContent='Press play. Magale begins at 0:58. ♡';if(wanted&&$('surprise-audio').paused)player.playVideo()},onStateChange:e=>{if(e.data===1)$('surprise-audio').pause();setPlaying(e.data===1);if(e.data===1)$('status').textContent='Playing a little music for my little world. ♡';if(e.data===2)$('status').textContent='Paused. Your letter is still right here.';if(e.data===0)$('status').textContent='Play it again, ammuu? ♡';},onError:()=>{$('status').textContent='The video couldn’t play here. Open it on YouTube below.';setPlaying(false);$('play').disabled=true;}}})};
$('play').onclick=()=>{$('surprise-audio').pause();if(!ready){wanted=true;$('status').textContent='Loading Magale… if it takes a while, use the YouTube link.';return}player.getPlayerState()===1?player.pauseVideo():player.playVideo()};
$('restart').onclick=()=>{$('surprise-audio').pause();if(ready){player.seekTo(58,true);player.playVideo()}};
$('seek').oninput=e=>{if(ready&&player.getDuration()>0)player.seekTo(58+Number(e.target.value)*(player.getDuration()-58)/100,true)};
$('volume').oninput=e=>{if(ready){player.unMute();player.setVolume(Number(e.target.value));$('mute').textContent='♪';$('mute').setAttribute('aria-label','Mute song')}};
$('mute').onclick=()=>{if(!ready)return;const muted=player.isMuted();muted?player.unMute():player.mute();$('mute').textContent=muted?'♪':'⌁';$('mute').setAttribute('aria-label',muted?'Mute song':'Unmute song')};
function parseLyrics(raw){let rows=raw.split('\n').map(s=>s.trim()).filter(Boolean);const re=/^\[(\d+):(\d+(?:\.\d+)?)\]\s*(.+)$/;timed=rows.some(s=>re.test(s));customLines=rows.map((s,i)=>{const m=s.match(re);return {time:m?Number(m[1])*60+Number(m[2]):i*12,text:m?m[3]:s}}).sort((a,b)=>a.time-b.time);lineIndex=-1;$('words-label').textContent=customLines.length?'02 / YOUR LYRICS':'02 / WORDS FROM MY HEART';$('words-note').textContent=customLines.length?(timed?'Your lyrics, timed to the music.':'Your lyrics change every 12 seconds. Add LRC timestamps for exact timing.'):'Little lines from your letter, as the music plays.';updateLine(0)}
function updateLine(t){let i=0,txt;if(customLines.length){for(let j=0;j<customLines.length;j++)if(t>=customLines[j].time)i=j;txt=t<customLines[0].time?'Your lyrics will begin with the music.':customLines[i].text}else{i=Math.floor(t/22)%letterLines.length;txt=letterLines[i]}if(i!==lineIndex||$('current-line').textContent!==txt){lineIndex=i;$('current-line').textContent=txt}}
setInterval(()=>{if(!ready)return;const t=player.getCurrentTime()||0,d=player.getDuration()||0;$('elapsed').textContent=format(Math.max(58,t));$('duration').textContent=d?format(d):'—:—';if(document.activeElement!==$('seek'))$('seek').value=d>58?Math.max(0,(t-58)/(d-58)*100):0;updateLine(Math.max(0,t-58))},500);
$('lyrics-open').onclick=()=>{$('lyrics-dialog').showModal()};
$('save-lyrics').onclick=()=>{const raw=$('lyrics-input').value;parseLyrics(raw);try{localStorage.setItem('sinduLyrics',raw)}catch{}$('lyrics-dialog').close();showToast(customLines.length?'Your lyrics are ready. ♡':'Letter lines restored. ♡')};
$('reset-lyrics').onclick=()=>{$('lyrics-input').value='';parseLyrics('');try{localStorage.removeItem('sinduLyrics')}catch{}$('lyrics-dialog').close()};
try{const raw=localStorage.getItem('sinduLyrics')||'';$('lyrics-input').value=raw;parseLyrics(raw)}catch{parseLyrics('')}
const wishes=['May your dreams find their way to the stars. ♡','Sirichitte iru ma. Your smile is my favourite. ♡','May this new year bring you happiness, health, and magic. ✧','Never forget how much you matter, Sindu ma. ♡'];let wishCount=0;
function wish(){showToast(wishes[wishCount++%wishes.length]);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<22;i++){const s=document.createElement('span');s.className='spark';s.textContent=i%3?'✧':'♡';s.style.left=Math.random()*100+'vw';s.style.top=(60+Math.random()*35)+'vh';s.style.animationDelay=Math.random()*.6+'s';document.body.appendChild(s);setTimeout(()=>s.remove(),3700)}}
$('wish').onclick=wish;$('wish-bottom').onclick=wish;
setTimeout(()=>{if(!ready)$('status').textContent='Music is taking a while to load. You can listen using the YouTube link below.'},15000);

const surpriseAudio=$('surprise-audio');
function syncSurprise(){const playing=!surpriseAudio.paused&&!surpriseAudio.ended;$('surprise-play').setAttribute('aria-pressed',String(playing));$('surprise-icon').textContent=playing?'Ⅱ':'▶';$('surprise-status').textContent=playing?'Playing your little surprise, Sindu ma. ♡':surpriseAudio.ended?'One more time, ammuu? ♡':surpriseAudio.currentTime>0?'Paused. Tap the button to keep listening. ♡':'Press it when you’re ready. ♡';}
$('surprise-play').onclick=async()=>{if(!surpriseAudio.paused){surpriseAudio.pause();return}wanted=false;if(ready)player.pauseVideo();if(surpriseAudio.ended)surpriseAudio.currentTime=0;try{await surpriseAudio.play()}catch{$('surprise-status').textContent='Couldn’t play the music. Please tap to try again.';}};
['play','pause','ended'].forEach(event=>surpriseAudio.addEventListener(event,syncSurprise));
surpriseAudio.addEventListener('error',()=>{$('surprise-status').textContent='The music couldn’t load. Please refresh and try again.'});
